package com.bank.arch;

import java.math.BigDecimal;
import java.util.logging.*;

public class ArchDemo {
    private static final Logger log = Logger.getLogger("Arch");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // MONOLITH: simple, one transaction spanning modules
        MonolithBank mono = new MonolithBank();
        mono.open("SAV2001", new BigDecimal("1000000"));
        mono.open("CUR3001", new BigDecimal("250000"));
        mono.transfer("SAV2001", "CUR3001", new BigDecimal("50000"));
        log.info(() -> "Monolith balances: " + mono.balances());

        // MICROSERVICES: independent services + saga for consistency
        AccountServiceClient accounts = new AccountServiceClient();
        accounts.open("SAV2001", new BigDecimal("1000000"));
        accounts.open("CUR3001", new BigDecimal("250000"));
        AuditServiceClient audit = new AuditServiceClient();
        TransferSaga saga = new TransferSaga(accounts, audit);

        // Happy path across services
        saga.transfer("SAV2001", "CUR3001", new BigDecimal("50000"));

        // Failure path: audit service down → compensate (undo the credit/debit)
        audit.setDown(true);
        saga.transfer("SAV2001", "CUR3001", new BigDecimal("20000"));
        log.info(() -> "Microservice balances after saga: " + accounts.balances());
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
