// ─── File: MonolithBank.java ───
package com.bank.arch;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

// One process, one DB, one transaction across modules.
public class MonolithBank {
    private static final Logger log = Logger.getLogger("Arch");
    private final Map<String, BigDecimal> accounts = new LinkedHashMap<>();
    private final List<String> audit = new ArrayList<>();

    public void open(String id, BigDecimal opening) { accounts.put(id, opening); }

    // in-process + single transaction: all-or-nothing is trivial
    public synchronized void transfer(String from, String to, BigDecimal amount) {
        if (accounts.get(from).compareTo(amount) < 0) throw new IllegalStateException("insufficient");
        accounts.put(from, accounts.get(from).subtract(amount));
        accounts.put(to, accounts.get(to).add(amount));
        audit.add("TRANSFER " + from + "->" + to + " Rs." + amount);
        log.info(() -> "Monolith committed transfer in one transaction");
    }
    public Map<String,BigDecimal> balances() { return accounts; }
}
```

