// ─── File: AccountServiceClient.java ───
package com.bank.arch;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

// Separate microservice with its OWN data, reached over the network.
public class AccountServiceClient {
    private static final Logger log = Logger.getLogger("Arch");
    private final Map<String, BigDecimal> accounts = new LinkedHashMap<>();
    public void open(String id, BigDecimal opening) { accounts.put(id, opening); }

    public void debit(String id, BigDecimal amount) {
        if (accounts.get(id).compareTo(amount) < 0) throw new IllegalStateException("insufficient");
        accounts.put(id, accounts.get(id).subtract(amount));
        log.info(() -> "[account-svc] debit " + id + " Rs." + amount);
    }
    public void credit(String id, BigDecimal amount) {
        accounts.put(id, accounts.get(id).add(amount));
        log.info(() -> "[account-svc] credit " + id + " Rs." + amount);
    }
    public Map<String,BigDecimal> balances() { return accounts; }
}
```

