package com.bank.arch;

import java.util.logging.*;

// Separate microservice; may be unavailable (network/independent failure).
public class AuditServiceClient {
    private static final Logger log = Logger.getLogger("Arch");
    private boolean down = false;
    public void setDown(boolean d) { this.down = d; }
    public void record(String entry) {
        if (down) throw new RuntimeException("[audit-svc] unavailable");
        log.info(() -> "[audit-svc] recorded " + entry);
    }
}
```

