// ─── File: TransferSaga.java ───
package com.bank.arch;

import java.math.BigDecimal;
import java.util.logging.*;

// Saga: coordinate steps across services; compensate if a later step fails.
public class TransferSaga {
    private static final Logger log = Logger.getLogger("Arch");
    private final AccountServiceClient accounts;
    private final AuditServiceClient audit;

    public TransferSaga(AccountServiceClient accounts, AuditServiceClient audit) {
        this.accounts = accounts; this.audit = audit;
    }

    public void transfer(String from, String to, BigDecimal amount) {
        accounts.debit(from, amount);      // step 1
        accounts.credit(to, amount);        // step 2
        try {
            audit.record("TRANSFER " + from + "->" + to + " Rs." + amount); // step 3
            log.info(() -> "Saga completed across services");
        } catch (RuntimeException e) {
            // compensating actions undo steps 1 and 2 (no distributed transaction)
            accounts.credit(from, amount);
            accounts.debit(to, amount);
            log.severe(() -> "Saga step failed: " + e.getMessage() + " → compensated (rolled back)");
        }
    }
}
```
